<script>
import {data,updateData,notify} from '../lib/store.js';import {SERVICE_INDICATORS,UNIVERSITY_TODOS,TASK_NAV,TASK_DETAILS,DIRECTORY_LINKS} from '../lib/workspace-directory.js';import Account from './Account.svelte';import Icon from '../lib/components/Icon.svelte';
let {route}=$props();let view=$derived(route.split('/')[1]??'indicators');let detail=$derived(TASK_DETAILS.find(t=>t.href===`#/${route}`));let query=$state('');let sort=$state('Name A–Z');let status=$state('All statuses');
let records=$derived((view==='to-do'?UNIVERSITY_TODOS:SERVICE_INDICATORS).filter(t=>`${t.label} ${t.department}`.toLowerCase().includes(query.toLowerCase())&&(status==='All statuses'||t.status===status)).toSorted((a,b)=>sort==='Name Z–A'?b.label.localeCompare(a.label):sort==='Department'?a.department.localeCompare(b.department):a.label.localeCompare(b.label)));
function review(id){const list=$data.workspace.reviewedTasks;updateData({...$data,workspace:{...$data.workspace,reviewedTasks:list.includes(id)?list.filter(x=>x!==id):[...list,id]}});notify(list.includes(id)?'Local review note removed.':'Local review noted. Official task status is unchanged.');}
</script>
<div class="page-heading"><div><p class="eyebrow">Know what needs your attention</p><h1>Tasks</h1><p>Service indicators, university-style sample tasks, and your personal reminders.</p></div><span class="badge neutral">Sample university records</span></div>
<nav class="profile-section-tabs" aria-label="Task sections">{#each TASK_NAV as p}<a href={p.href} aria-current={p.id===view?'page':undefined}><Icon name={p.icon} size={16}/>{p.label}{#if p.id!=='reminders'}<span class="badge neutral">{p.id==='indicators'?SERVICE_INDICATORS.length:UNIVERSITY_TODOS.length}</span>{/if}</a>{/each}</nav>
{#if view==='reminders'}<Account route="tasks"/>
{:else if detail}<nav class="academic-breadcrumb" aria-label="Task breadcrumb"><a href={detail.group==='Service Indicators'?'#/tasks/indicators':'#/tasks/to-do'}>{detail.group}</a><Icon name="chevron" size={12}/><span>{detail.label}</span></nav><section class="panel padded academic-copy"><div class="section-heading"><h2>{detail.label}</h2><span class="badge neutral">{detail.status??'Sample indicator'}</span></div><dl class="academic-definition"><div><dt>Department</dt><dd>{detail.department}</dd></div><div><dt>Due date</dt><dd>No official date is connected</dd></div>{#if detail.impact}<div><dt>Impact</dt><dd>{detail.impact}</dd></div>{/if}</dl><p>{detail.description}</p><a class="button primary" href={detail.action} target={detail.action.startsWith('https:')?'_blank':undefined} rel={detail.action.startsWith('https:')?'noreferrer':undefined}>{detail.actionLabel}<Icon name={detail.action.startsWith('https:')?'external':'arrow'} size={16}/></a>{#if detail.group==='To Do List'}<div class="notice spaced"><Icon name="info"/><p>Local review notes help you track what you looked at. They do not submit documents, complete an official requirement, or clear a service indicator.</p></div><button class="button secondary spaced" aria-pressed={$data.workspace.reviewedTasks.includes(detail.id)} onclick={()=>review(detail.id)}>{$data.workspace.reviewedTasks.includes(detail.id)?'Remove local review note':'Mark reviewed locally'}</button>{/if}</section>
{:else if ['indicators','to-do'].includes(view)}<section class="panel padded"><div class="section-heading"><h2>{view==='indicators'?'Service Indicators':'To Do List'}</h2><span class="badge neutral">{records.length} of {view==='to-do'?UNIVERSITY_TODOS.length:SERVICE_INDICATORS.length} items</span></div><div class="academic-controls spaced"><div class="search-box"><Icon name="search" size={17}/><input type="search" aria-label="Search task records" placeholder="Search by task or department…" bind:value={query}/></div><label>Sort by<select bind:value={sort}><option>Name A–Z</option><option>Name Z–A</option><option>Department</option></select></label>{#if view==='to-do'}<label>Status<select bind:value={status}><option>All statuses</option><option>Assigned</option><option>Initiated</option></select></label>{/if}</div><div class="table-scroll"><table class="academic-table"><thead><tr><th>{view==='indicators'?'Hold / Indicator':'Task'}</th>{#if view==='to-do'}<th>Due Date</th><th>Status</th>{/if}<th>Department</th><th>Details</th></tr></thead><tbody>{#each records as row}<tr><td><strong>{row.label}</strong>{#if view==='indicators'}<small>Informational sample</small>{/if}</td>{#if view==='to-do'}<td>Not provided</td><td><span class="badge neutral">{row.status}</span>{#if $data.workspace.reviewedTasks.includes(row.id)}<small>Reviewed locally</small>{/if}</td>{/if}<td>{row.department}</td><td><a class="text-link" href={row.href} aria-label={`View ${row.label} details`}>View<Icon name="chevron" size={15}/></a></td></tr>{/each}</tbody></table></div>{#if !records.length}<div class="empty-state"><h3>No matching records.</h3><p>Try another search or status.</p><button class="button secondary spaced" onclick={()=>{query='';status='All statuses';}}>Clear filters</button></div>{/if}<p class="fine-print">These sample records illustrate the original Tasks hierarchy. They do not describe your real account, tax position, or health status. Personal checklist completion does not clear university holds.</p><a class="text-link spaced" href={DIRECTORY_LINKS.help} target="_blank" rel="noreferrer">Official instructions for outstanding items<Icon name="external" size={15}/></a></section>
{:else}<section class="panel empty-state"><h2>Task page not found.</h2><a class="button primary" href="#/tasks">Back to Tasks</a></section>{/if}
